-- 51 Night Bloom: walks the camera along the meadow and counts what the
-- flowers say. Each flower's opening is its own script, called by the
-- engine through `visibility_notifier`. Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/51-night-bloom.scene"
local COUNT = 40
local REACH = 1160.0
local captions = true
local drifting = true
local cam, hills, status
local t, x = 0, 0
local dir = 1
local awake = 0

function init(entity)
    cam = Entity.find_by_name("Camera")
    hills = Entity.find_by_name("Hills")
    status = Entity.find_by_name("Status")
    Event.on("bloom", entity)
end

function on_bloom(entity, data)
    awake = awake + ((data and data.d) or 0)
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("Space") then drifting = not drifting end
    t = t + dt
    local walk = 0
    if Input.is_key_pressed("Left") then walk = walk - 1 end
    if Input.is_key_pressed("Right") then walk = walk + 1 end
    if walk ~= 0 then drifting = false end
    if drifting then
        x = x + 110 * dt * dir
        if x >= REACH then dir = -1 elseif x <= -REACH then dir = 1 end
    else
        x = x + walk * 420 * dt
    end
    x = math.max(-REACH, math.min(REACH, x))
    Transform.set_position(cam, x, 0)
    if hills then Transform.set_position(hills, x * 0.5, -110.0) end
    if status then
        UI.set_text(status, "open " .. awake .. " of " .. COUNT .. " - the rest hold still off screen")
    end
end
